// Return a vector containing the last character of each inner vector.
// Assumes every inner vector is non-empty; the outer vector may be empty.
fn extract_rear_chars(l: &Vec<Vec<char>>) -> Vec<char> {
    l.iter()
        .map(|inner| *inner.last().expect("inner vectors are non-empty"))
        .collect()
}

